import{_ as o,o as t,c as a,aS as i}from"./chunks/framework.DsJaIkSj.js";const _=JSON.parse('{"title":"文档贡献规范","description":"","frontmatter":{},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md","lastUpdated":null}'),l={name:"contributing.md"};function r(c,e,d,n,s,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="文档贡献规范" tabindex="-1">文档贡献规范 <a class="header-anchor" href="#文档贡献规范" aria-label="Permalink to &quot;文档贡献规范&quot;">​</a></h1><p>文档门户只承诺源码、<code>package.json</code>、exports、类型声明、测试和现有 playground/Doc.vue 能证明的能力。包 README 继续承担包内快速参考；门户负责选型、安装/import、宿主前置、公开能力导航、真实示例和边界。</p><h2 id="组件-doc-vue-最小结构" tabindex="-1">组件 Doc.vue 最小结构 <a class="header-anchor" href="#组件-doc-vue-最小结构" aria-label="Permalink to &quot;组件 Doc.vue 最小结构&quot;">​</a></h2><p>新增或明显扩展组件文档时，按以下顺序提供可定位章节：</p><ol><li>用途与选型：说明解决的问题和不负责的业务边界。</li><li>安装与 import：使用公开根入口或已声明子入口，不引用 <code>src</code>、<code>lib</code> 或私有构建路径。</li><li>基础与受控示例：小例子用于入门；受控值、默认值和事件日志来自真实组件。</li><li>状态与异常：只记录源码和声明已证明的 loading、disabled、empty、error、retry 或回滚语义。</li><li>Props、Events、Slots、Expose：字段、参数和方法必须能回读到公开声明或实现；不把 Element Plus/VXE 实例、私有 DOM/VNode/Node/Store 写成公共 API。</li><li>样式与主题：说明 Qy tokens、局部滚动、尺寸或宿主主题前置；不要把 <code>--el-*</code> 作为业务协议。</li><li>边界：明确未实现、兼容入口、fallback、Deferred 或需要宿主注入的能力。</li></ol><h2 id="门户页面与验收夹具" tabindex="-1">门户页面与验收夹具 <a class="header-anchor" href="#门户页面与验收夹具" aria-label="Permalink to &quot;门户页面与验收夹具&quot;">​</a></h2><ul><li>registry 是页面、导航、版本和 export→文档覆盖的唯一派生源；新增 <code>@qynpm/ui</code> 子入口必须登记为独立页面、父组件页面覆盖或迁移/兼容入口。</li><li>复合子组件共用父页面时，增加 export 覆盖映射，不为同一交互重复创建推荐页面。</li><li><code>virtual-table</code>、<code>virtual-table-lazy</code>、<code>table-span</code> 和 10,000×100 组合只作为性能/组合实验室或验收入口，不作为 QyTable 入门教程。</li><li>示例使用本地 mock；不得写入真实账号、token、接口地址、内部域名、绝对本机路径或生产数据。</li><li>修改文档后运行对应的 registry/page test、<code>pnpm docs:test</code> 和 <code>git diff --check</code>；影响静态产物时再运行 docs build/artifact/audit。</li></ul>',7)])])}const m=o(l,[["render",r]]);export{_ as __pageData,m as default};
